// Practice for Level 3, Objects and classes: four or five exercises per lesson, all set in Old Hoot’s robot workshop.
// Same format as exercises.js. Every word is our own.
const SX_BOT_PY = 'class Robot:\n    def __init__(self, name):\n        self.name = name\n\n    def beep(self):\n        print(self.name, "beeps")\n\n';
const SX_BOT_JS = 'class Robot {\n  constructor(name) {\n    this.name = name;\n  }\n  beep() {\n    console.log(this.name, "beeps");\n  }\n}\n\n';
const SX_WORK_PY = 'class Robot:\n    def __init__(self, name):\n        self.name = name\n        self.battery = 100\n\n    def work(self):\n        self.battery = self.battery - 30\n\n';
const SX_WORK_JS = 'class Robot {\n  constructor(name) {\n    this.name = name;\n    this.battery = 100;\n  }\n  work() {\n    this.battery = this.battery - 30;\n  }\n}\n\n';
const SX_GUARD_PY = 'class Robot:\n    def __init__(self):\n        self._battery = 50\n\n    def charge(self, n):\n        if n > 0:\n            self._battery = min(100, self._battery + n)\n\n';
const SX_GUARD_JS = 'class Robot {\n  constructor() {\n    this._battery = 50;\n  }\n  charge(n) {\n    if (n > 0) {\n      this._battery = Math.min(100, this._battery + n);\n    }\n  }\n}\n\n';
const SX_ABC_PY = 'from abc import ABC, abstractmethod\n\nclass Worker(ABC):\n    @abstractmethod\n    def work(self):\n        pass\n\n';
const SX_ABC_JS = 'class Worker {\n  constructor() {\n    if (new.target === Worker) throw new Error("Worker is a contract");\n  }\n  work() {\n    throw new Error("work() is missing");\n  }\n}\n\n';
const SX_TEAM_PY = 'class Robot:\n    def __init__(self, name):\n        self.name = name\n\nclass Cleaner(Robot):\n    def work(self):\n        return "sweeps"\n\nclass Courier(Robot):\n    def work(self):\n        return "delivers"\n\n';
const SX_TEAM_JS = 'class Robot {\n  constructor(name) {\n    this.name = name;\n  }\n}\n\nclass Cleaner extends Robot {\n  work() {\n    return "sweeps";\n  }\n}\n\nclass Courier extends Robot {\n  work() {\n    return "delivers";\n  }\n}\n\n';
const SX_BAT_PY = 'class Battery:\n    def __init__(self):\n        self.level = 100\n\n';
const SX_BAT_JS = 'class Battery {\n  constructor() {\n    this.level = 100;\n  }\n}\n\n';

